@GET
@Path("/contratos")
@Authenticated
public List<ContratoDTO> listar(@QueryParam("pagina") int pagina) {
    return repositorio.listAll(Page.of(pagina, 50)).stream().map(ContratoDTO::de).toList();
}

@DELETE
@Path("/anexos/{id}")
@Authenticated
public Response remover(@PathParam("id") Long id) {
    Anexo anexo = Anexo.findById(id);
    anexo.delete();
    return Response.noContent().build();
}

@POST
@Path("/admin/usuarios/{id}/promover")
@Authenticated   // <- sem @RolesAllowed
public Response promover(@PathParam("id") Long id) {
    usuarioService.promoverParaAdmin(id);
    return Response.ok().build();
}
